import dlt
from pyspark.sql import functions as F
from pyspark.sql.types import *
import json
import uuid
from datetime import datetime

# Kafka configuration - these should be set as pipeline configuration
KAFKA_BOOTSTRAP_SERVERS = spark.conf.get("pipelines.kafka.bootstrap.servers", "kafka-cluster.megamart.internal:9092")
KAFKA_TOPIC = "pos-transactions-v1"
CHECKPOINT_LOCATION = "s3://megamart-data-lake-prod/checkpoints/bronze_pos_transactions_kafka/"

