# MAGIC %md
# MAGIC ## Schema Definition

# COMMAND ----------

# Define the expected schema for POS transaction messages
pos_transaction_schema = StructType([
    StructField("transaction_id", StringType(), False),
    StructField("store_id", StringType(), False),
    StructField("register_id", StringType(), False),
    StructField("cashier_id", StringType(), True),
    StructField("customer_id", StringType(), True),
    StructField("transaction_timestamp", TimestampType(), False),
    StructField("items", StringType(), False),  # JSON string
    StructField("subtotal", DecimalType(15,2), False),
    StructField("tax_amount", DecimalType(10,2), False),
    StructField("discount_amount", DecimalType(10,2), True),
    StructField("total_amount", DecimalType(15,2), False),
    StructField("payment_method", StringType(), False),
    StructField("payment_details", StringType(), True),
    StructField("receipt_number", StringType(), True),
    StructField("promotion_codes", StringType(), True),  # JSON string
    StructField("loyalty_points_earned", IntegerType(), True),
    StructField("loyalty_points_redeemed", IntegerType(), True)
])

