# MAGIC %md
# MAGIC ## Data Quality Functions

# COMMAND ----------

def validate_transaction_data(df):
    """Apply data quality validations to transaction data"""
    
    # Add data quality flags
    df = df.withColumn(
        "dq_transaction_id_valid",
        F.when(
            (F.col("transaction_id").isNotNull()) & 
            (F.length("transaction_id") >= 10), 
            True
        ).otherwise(False)
    )
    
    df = df.withColumn(
        "dq_amounts_valid",
        F.when(
            (F.col("total_amount") > 0) & 
            (F.col("subtotal") > 0) &
            (F.abs(F.col("total_amount") - (
                F.col("subtotal") + 
                F.coalesce(F.col("tax_amount"), F.lit(0)) - 
                F.coalesce(F.col("discount_amount"), F.lit(0))
            )) < 0.01),
            True
        ).otherwise(False)
    )
    
    df = df.withColumn(
        "dq_store_format_valid",
        F.when(F.col("store_id").rlike("^STORE_[0-9]{4}$"), True).otherwise(False)
    )
    
    df = df.withColumn(
        "dq_timestamp_valid",
        F.when(
            (F.col("transaction_timestamp").isNotNull()) &
            (F.col("transaction_timestamp") > F.current_timestamp() - F.expr("INTERVAL 1 DAY")) &
            (F.col("transaction_timestamp") <= F.current_timestamp()),
            True
        ).otherwise(False)
    )
    
    df = df.withColumn(
        "dq_items_valid",
        F.when(
            (F.col("items").isNotNull()) & 
            (F.length("items") > 0) & 
            (F.col("items") != "[]"),
            True
        ).otherwise(False)
    )
    
    # Overall data quality score (percentage of checks passed)
    df = df.withColumn(
        "data_quality_score",
        (
            F.col("dq_transaction_id_valid").cast("int") +
            F.col("dq_amounts_valid").cast("int") +
            F.col("dq_store_format_valid").cast("int") +
            F.col("dq_timestamp_valid").cast("int") +
            F.col("dq_items_valid").cast("int")
        ) / 5.0 * 100
    )
    
    return df

def parse_kafka_message(df):
    """Parse Kafka message structure and extract transaction data"""
    
    # Parse the Kafka value as JSON
    df = df.withColumn("value_json", F.from_json(F.col("value").cast("string"), pos_transaction_schema))
    
    # Extract all fields from the nested JSON structure
    df = df.select(
        # Kafka metadata
        F.col("partition").alias("kafka_partition"),
        F.col("offset").alias("kafka_offset"),
        F.col("timestamp").alias("kafka_timestamp"),
        F.col("timestampType").alias("kafka_timestamp_type"),
        
        # Transaction data
        F.col("value_json.transaction_id").alias("transaction_id"),
        F.col("value_json.store_id").alias("store_id"),
        F.col("value_json.register_id").alias("register_id"),
        F.col("value_json.cashier_id").alias("cashier_id"),
        F.col("value_json.customer_id").alias("customer_id"),
        F.col("value_json.transaction_timestamp").alias("transaction_timestamp"),
        F.col("value_json.items").alias("items"),
        F.col("value_json.subtotal").alias("subtotal"),
        F.col("value_json.tax_amount").alias("tax_amount"),
        F.col("value_json.discount_amount").alias("discount_amount"),
        F.col("value_json.total_amount").alias("total_amount"),
        F.col("value_json.payment_method").alias("payment_method"),
        F.col("value_json.payment_details").alias("payment_details"),
        F.col("value_json.receipt_number").alias("receipt_number"),
        F.col("value_json.promotion_codes").alias("promotion_codes"),
        F.col("value_json.loyalty_points_earned").alias("loyalty_points_earned"),
        F.col("value_json.loyalty_points_redeemed").alias("loyalty_points_redeemed")
    )
    
    # Add derived fields
    df = df.withColumn(
        "transaction_date",
        F.to_date("transaction_timestamp")
    )
    
    df = df.withColumn(
        "ingested_at",
        F.current_timestamp()
    )
    
    return df

def enrich_transaction_data(df):
    """Add business logic and enrichments to transaction data"""
    
    # Clean and standardize payment method
    df = df.withColumn(
        "payment_method_clean",
        F.upper(F.trim(F.col("payment_method")))
    )
    
    # Extract item count from JSON
    df = df.withColumn(
        "item_count",
        F.when(
            (F.col("items").isNotNull()) & (F.col("items") != "") & (F.col("items") != "[]"),
            F.size(F.from_json(F.col("items"), "array<struct<product_id:string,quantity:int>>"))
        ).otherwise(0)
    )
    
    # Extract total quantity from JSON items
    df = df.withColumn(
        "total_quantity",
        F.when(
            (F.col("items").isNotNull()) & (F.col("items") != "") & (F.col("items") != "[]"),
            F.aggregate(
                F.from_json(F.col("items"), "array<struct<quantity:int>>"),
                F.lit(0),
                lambda acc, x: acc + F.coalesce(x.quantity, F.lit(0))
            )
        ).otherwise(0)
    )
    
    # Extract promotion count
    df = df.withColumn(
        "promotion_count",
        F.when(
            (F.col("promotion_codes").isNotNull()) & 
            (F.col("promotion_codes") != "") & 
            (F.col("promotion_codes") != "[]"),
            F.size(F.from_json(F.col("promotion_codes"), "array<string>"))
        ).otherwise(0)
    )
    
    # Calculate net loyalty points
    df = df.withColumn(
        "net_loyalty_points",
        F.coalesce(F.col("loyalty_points_earned"), F.lit(0)) - 
        F.coalesce(F.col("loyalty_points_redeemed"), F.lit(0))
    )
    
    # Determine if discount was applied
    df = df.withColumn(
        "discount_applied",
        F.when(
            (F.coalesce(F.col("discount_amount"), F.lit(0)) > 0) |
            (F.col("promotion_count") > 0) |
            (F.coalesce(F.col("loyalty_points_redeemed"), F.lit(0)) > 0),
            True
        ).otherwise(False)
    )
    
    # Customer type classification
    df = df.withColumn(
        "customer_type",
        F.when(F.col("customer_id").isNotNull(), "Member").otherwise("Guest")
    )
    
    # Transaction size classification
    df = df.withColumn(
        "transaction_size",
        F.when(F.col("total_amount") < 10, "Small")
         .when(F.col("total_amount") < 50, "Medium")
         .when(F.col("total_amount") < 200, "Large")
         .otherwise("Very Large")
    )
    
    return df

