@dlt.table(
    name="pos_transactions",
    comment="Real-time POS transactions from Kafka with data quality validations",
    table_properties={
        "delta.enableChangeDataFeed": "true",
        "delta.autoOptimize.optimizeWrite": "true",
        "delta.autoOptimize.autoCompact": "true",
        "pipelines.reset.allowed": "false"
    },
    partition_cols=["transaction_date"],
    path="s3://megamart-data-lake-prod/bronze/streaming/pos_transactions/"
)
@dlt.expect_all({
    "valid_transaction_id": "transaction_id IS NOT NULL AND length(transaction_id) >= 10",
    "positive_amounts": "total_amount > 0 AND subtotal > 0",
    "valid_timestamp": "transaction_timestamp IS NOT NULL",
    "valid_store_format": "store_id RLIKE '^STORE_[0-9]{4}$'",
    "items_present": "items IS NOT NULL AND length(items) > 0",
    "amounts_balance": "ABS(total_amount - (subtotal + COALESCE(tax_amount, 0) - COALESCE(discount_amount, 0))) < 0.01"
})
def bronze_pos_transactions():
    """
    Bronze layer streaming table for POS transactions from Kafka.
    
    Applies JSON parsing, data quality checks, and basic enrichments.
    """
    
    # Read from Kafka topic
    kafka_df = (
        spark.readStream
        .format("kafka")
        .option("kafka.bootstrap.servers", KAFKA_BOOTSTRAP_SERVERS)
        .option("subscribe", KAFKA_TOPIC)
        .option("startingOffsets", "latest")
        .option("maxOffsetsPerTrigger", 10000)
        .option("kafka.security.protocol", "SASL_SSL")
        .option("kafka.sasl.mechanism", "PLAIN")
        .option("failOnDataLoss", "false")
        .load()
    )
    
    # Parse Kafka messages
    parsed_df = parse_kafka_message(kafka_df)
    
    # Apply data quality validations
    validated_df = validate_transaction_data(parsed_df)
    
    # Add business enrichments
    enriched_df = enrich_transaction_data(validated_df)
    
    # Filter out messages that fail critical validations
    filtered_df = enriched_df.filter(
        (F.col("dq_transaction_id_valid") == True) &
        (F.col("dq_amounts_valid") == True) &
        (F.col("dq_timestamp_valid") == True) &
        (F.col("dq_items_valid") == True) &
        # Exclude test transactions
        (~F.col("store_id").like("%TEST%")) &
        (~F.col("cashier_id").isin(["TEST_USER", "TRAINING_USER"]))
    )
    
    return filtered_df

