@dlt.table(
    name="pos_transactions_quality_metrics",
    comment="Data quality metrics for POS transactions stream",
    table_properties={
        "delta.enableChangeDataFeed": "true"
    }
)
def pos_transactions_quality_metrics():
    """
    Data quality monitoring table for POS transactions.
    
    Tracks validation failures and data quality trends over time.
    """
    
    base_df = dlt.read_stream("pos_transactions")
    
    # Aggregate quality metrics by time windows
    quality_df = (
        base_df
        .withWatermark("kafka_timestamp", "5 minutes")
        .groupBy(
            F.window("kafka_timestamp", "5 minutes").alias("time_window"),
            "store_id"
        )
        .agg(
            F.count("*").alias("total_records"),
            F.sum(F.col("dq_transaction_id_valid").cast("int")).alias("valid_transaction_ids"),
            F.sum(F.col("dq_amounts_valid").cast("int")).alias("valid_amounts"),
            F.sum(F.col("dq_store_format_valid").cast("int")).alias("valid_store_formats"),
            F.sum(F.col("dq_timestamp_valid").cast("int")).alias("valid_timestamps"),
            F.sum(F.col("dq_items_valid").cast("int")).alias("valid_items"),
            F.avg("data_quality_score").alias("avg_quality_score"),
            F.min("data_quality_score").alias("min_quality_score"),
            F.max("data_quality_score").alias("max_quality_score"),
            F.sum("total_amount").alias("total_revenue"),
            F.count("transaction_id").alias("processed_transactions"),
            F.current_timestamp().alias("processed_at")
        )
    )
    
    # Calculate quality rates
    quality_df = quality_df.withColumn(
        "transaction_id_quality_rate",
        F.col("valid_transaction_ids") / F.col("total_records") * 100
    ).withColumn(
        "amounts_quality_rate", 
        F.col("valid_amounts") / F.col("total_records") * 100
    ).withColumn(
        "overall_quality_rate",
        (F.col("valid_transaction_ids") + F.col("valid_amounts") + 
         F.col("valid_store_formats") + F.col("valid_timestamps") + F.col("valid_items")) / 
        (F.col("total_records") * 5) * 100
    )
    
    return quality_df

