# MAGIC ## Error Handling and Dead Letter Queue

# COMMAND ----------

@dlt.table(
    name="pos_transactions_errors",
    comment="Failed POS transactions for investigation and reprocessing",
    table_properties={
        "delta.enableChangeDataFeed": "true"
    }
)
def pos_transactions_errors():
    """
    Dead letter queue for POS transactions that fail critical validations.
    
    Captures failed records for investigation and potential reprocessing.
    """
    
    # Read the raw stream again for error capture
    kafka_df = (
        spark.readStream
        .format("kafka")
        .option("kafka.bootstrap.servers", KAFKA_BOOTSTRAP_SERVERS)
        .option("subscribe", KAFKA_TOPIC)
        .option("startingOffsets", "latest")
        .option("maxOffsetsPerTrigger", 10000)
        .option("failOnDataLoss", "false")
        .load()
    )
    
    # Parse and validate
    parsed_df = parse_kafka_message(kafka_df)
    validated_df = validate_transaction_data(parsed_df)
    
    # Capture only failed records
    error_df = validated_df.filter(
        (F.col("dq_transaction_id_valid") == False) |
        (F.col("dq_amounts_valid") == False) |
        (F.col("dq_timestamp_valid") == False) |
        (F.col("dq_items_valid") == False) |
        # Also capture test transactions
        (F.col("store_id").like("%TEST%")) |
        (F.col("cashier_id").isin(["TEST_USER", "TRAINING_USER"]))
    )
    
    # Add error categorization
    error_df = error_df.withColumn(
        "error_category",
        F.when(~F.col("dq_transaction_id_valid"), "INVALID_TRANSACTION_ID")
         .when(~F.col("dq_amounts_valid"), "INVALID_AMOUNTS")  
         .when(~F.col("dq_timestamp_valid"), "INVALID_TIMESTAMP")
         .when(~F.col("dq_items_valid"), "INVALID_ITEMS")
         .when(F.col("store_id").like("%TEST%"), "TEST_TRANSACTION")
         .otherwise("OTHER_ERROR")
    )
    
    # Add error details
    error_df = error_df.withColumn(
        "error_details",
        F.struct(
            F.col("dq_transaction_id_valid").alias("transaction_id_valid"),
            F.col("dq_amounts_valid").alias("amounts_valid"),
            F.col("dq_store_format_valid").alias("store_format_valid"),
            F.col("dq_timestamp_valid").alias("timestamp_valid"),
            F.col("dq_items_valid").alias("items_valid"),
            F.col("data_quality_score").alias("quality_score")
        )
    )
    
    error_df = error_df.withColumn("error_timestamp", F.current_timestamp())
    
    return error_df

